SELECT s.subject || ' — в таблице FR ' || s.said || ', в наборе ' || count(r.id) AS detail FROM project_traceability_said s LEFT JOIN project_requirements r ON r.project_id = s.project_id AND r.kind = 'FR' AND r.area = s.subject WHERE s.project_id = $1 AND s.column_name = 'FR' AND NOT s.is_total GROUP BY s.subject, s.said HAVING s.said <> count(r.id) UNION ALL SELECT r.area || ' — подсистема есть в наборе (' || count(*) || ' FR), а таблицы о ней нет' FROM project_requirements r WHERE r.project_id = $1 AND r.kind = 'FR' AND r.area <> '' AND NOT EXISTS (SELECT 1 FROM project_traceability_said s WHERE s.project_id = r.project_id AND s.column_name = 'FR' AND s.subject = r.area) GROUP BY r.area UNION ALL SELECT 'итог таблицы подсистем: ' || s.said || ', а FR в наборе ' || (SELECT count(*) FROM project_requirements WHERE project_id = $1 AND kind = 'FR') FROM project_traceability_said s WHERE s.project_id = $1 AND s.column_name = 'FR' AND s.is_total AND s.said <> (SELECT count(*) FROM project_requirements WHERE project_id = $1 AND kind = 'FR') ORDER BY 1
